def transform(grid):
    if not grid or not grid[0]:
        return grid

    from collections import Counter

    # Determine background color as the most frequent color in the grid
    bg = Counter(val for row in grid for val in row).most_common(1)[0][0]

    n, m = len(grid), len(grid[0])
    result = [row[:] for row in grid]
    changes = {}

    # 1 affects orthogonal neighbors (up, down, left, right) -> turns them to 7
    # 2 affects diagonal neighbors (top-left, top-right, bottom-left, bottom-right) -> turns them to 4
    # Only cells with the background color are affected/supplied
    # Inert cells (6, 8) and sources (1, 2) are preserved unless targeted (but sources are typically != bg)

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 1:
                # Orthogonal neighbors
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        if grid[nr][nc] == bg:
                            changes[(nr, nc)] = 7
            elif grid[r][c] == 2:
                # Diagonal neighbors
                for dr, dc in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        if grid[nr][nc] == bg:
                            changes[(nr, nc)] = 4

    for (r, c), val in changes.items():
        result[r][c] = val

    return result
